const b = (msg.payload && typeof msg.payload === 'object') ? msg.payload : {};
const email = typeof b.email === 'string' ? b.email.trim().toLowerCase() : '';
const pw = typeof b.password === 'string' ? b.password : '';
const name = typeof b.display_name === 'string' ? b.display_name.trim() : '';
const bad = (details) => { msg.statusCode = 400; msg.payload = { error: 'VALIDATION', details: details }; return [null, msg]; };
if (!email || email.length > 191 || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return bad('รูปแบบอีเมลไม่ถูกต้อง');
if (pw.length < 8) return bad('รหัสผ่านต้องยาวอย่างน้อย 8 ตัวอักษร');
if (Buffer.byteLength(pw, 'utf8') > 72) return bad('รหัสผ่านยาวเกินไป');
if (!name || name.length > 100) return bad('กรุณากรอกชื่อที่ใช้แสดง (ไม่เกิน 100 ตัวอักษร)');
const hash = await global.get('bcrypt').hash(pw, 10);
msg.topic = 'INSERT INTO users (email, password_hash, display_name) VALUES (?, ?, ?)';
msg.payload = [email, hash, name];
msg.newUser = { email: email, display_name: name };
return [msg, null];

const id = msg.payload.insertId;
const jwt = global.get('jwt');
const token = jwt.sign({ sub: String(id), email: msg.newUser.email }, env.get('JWT_SECRET'),
  { algorithm: 'HS256', expiresIn: env.get('JWT_EXPIRES_IN') || '7d' });
msg.statusCode = 201;
msg.payload = { token: token, user: { id: id, email: msg.newUser.email, display_name: msg.newUser.display_name } };
delete msg.newUser;
return msg;

// กัน brute force: ผิดครบ 5 ครั้งใน 5 นาทีต่อ email → 429 (เก็บใน flow context ชื่อ loginFails)
const WINDOW = 5 * 60 * 1000, MAX = 5;
const b = (msg.payload && typeof msg.payload === 'object') ? msg.payload : {};
const email = typeof b.email === 'string' ? b.email.trim().toLowerCase() : '';
const pw = typeof b.password === 'string' ? b.password : '';
if (!email || !pw) {
  msg.statusCode = 400;
  msg.payload = { error: 'VALIDATION', details: 'กรุณากรอกอีเมลและรหัสผ่าน' };
  return [null, msg];
}
const now = Date.now();
const fails = flow.get('loginFails') || {};
for (const k of Object.keys(fails)) {
  fails[k] = fails[k].filter(t => now - t < WINDOW);
  if (!fails[k].length) delete fails[k];
}
flow.set('loginFails', fails);
const arr = fails[email] || [];
if (arr.length >= MAX) {
  const wait = Math.ceil((WINDOW - (now - arr[0])) / 1000);
  msg.statusCode = 429;
  msg.headers = { 'Retry-After': String(wait) };
  msg.payload = { error: 'TOO_MANY_ATTEMPTS', details: 'ลองเข้าสู่ระบบผิดหลายครั้งเกินไป กรุณารอประมาณ ' + Math.ceil(wait / 60) + ' นาทีแล้วลองใหม่' };
  return [null, msg];
}
msg.loginEmail = email;
msg.loginPassword = pw;
msg.topic = 'SELECT id, email, password_hash, display_name FROM users WHERE email = ? LIMIT 1';
msg.payload = [email];
return [msg, null];

const row = Array.isArray(msg.payload) ? msg.payload[0] : null;
// ไม่พบ email ก็ยัง compare กับ hash หลอก เพื่อให้เวลาตอบใกล้เคียงกัน (กัน user enumeration)
let dummy = context.get('dummy');
if (!dummy) { dummy = await global.get('bcrypt').hash('yatung-dummy-password', 10); context.set('dummy', dummy); }
const ok = await global.get('bcrypt').compare(msg.loginPassword, row ? row.password_hash : dummy);
const email = msg.loginEmail;
const fails = flow.get('loginFails') || {};
delete msg.loginPassword; delete msg.loginEmail;
if (!row || !ok) {
  (fails[email] = fails[email] || []).push(Date.now());
  flow.set('loginFails', fails);
  msg.statusCode = 401;
  msg.payload = { error: 'INVALID_CREDENTIALS', details: 'อีเมลหรือรหัสผ่านไม่ถูกต้อง' };
  return msg;
}
delete fails[email];
flow.set('loginFails', fails);
const jwt = global.get('jwt');
const token = jwt.sign({ sub: String(row.id), email: row.email }, env.get('JWT_SECRET'),
  { algorithm: 'HS256', expiresIn: env.get('JWT_EXPIRES_IN') || '7d' });
msg.statusCode = 200;
msg.payload = { token: token, user: { id: row.id, email: row.email, display_name: row.display_name } };
return msg;

msg.topic = 'SELECT u.id, u.email, u.display_name, u.line_user_id, u.line_link_code, u.tts_rate, s.slot, s.slot_time ' +
  'FROM users u LEFT JOIN user_slot_times s ON s.user_id = u.id WHERE u.id = ?';
msg.payload = [msg.user.id];
return msg;

const rows = Array.isArray(msg.payload) ? msg.payload : [];
if (!rows.length) {
  msg.statusCode = 401;
  msg.payload = { error: 'UNAUTHORIZED', details: 'ไม่พบบัญชีผู้ใช้ กรุณาเข้าสู่ระบบใหม่' };
  return msg;
}
const u = rows[0];
const order = ['morning', 'noon', 'evening', 'bedtime'];
const times = {};
for (const r of rows) if (r.slot) times[r.slot] = String(r.slot_time).slice(0, 5);
const slot_times = {};
for (const s of order) if (times[s]) slot_times[s] = times[s];
msg.statusCode = 200;
msg.payload = {
  id: u.id, email: u.email, display_name: u.display_name,
  line_linked: !!u.line_user_id, line_link_code: u.line_link_code,
  tts_rate: Number(u.tts_rate), slot_times: slot_times
};
return msg;

const m = String((msg.error && msg.error.message) || '');
if (m.indexOf('ER_DUP_ENTRY') !== -1 || m.indexOf('Duplicate entry') !== -1) {
  msg.statusCode = 409;
  msg.payload = { error: 'EMAIL_EXISTS', details: 'อีเมลนี้ถูกใช้สมัครแล้ว' };
} else {
  msg.statusCode = 500;
  msg.payload = { error: 'INTERNAL_ERROR', details: 'ระบบขัดข้อง กรุณาลองใหม่ภายหลัง' };
}
delete msg.loginPassword;
return msg;
